\begin{tikzpicture}[font=\sffamily, >=Stealth, x=1cm, y=1cm]
  % liquid in beaker
  \fill[black!10] (0,0) rectangle (7,3);
  % gas regions inside tubes (white)
  \fill[white] (1.2,3.0) rectangle (2.8,4.2);
  \fill[white] (4.2,1.8) rectangle (5.8,4.2);
  % beaker
  \draw[thick] (0,4.6) -- (0,0) -- (7,0) -- (7,4.6);
  \draw (0,3) -- (1.2,3) (2.8,3) -- (4.2,3) (5.8,3) -- (7,3);
  % tubes
  \draw[thick] (1.2,1) -- (1.2,4.0) arc (180:0:0.8) -- (2.8,1);
  \draw[thick] (4.2,1) -- (4.2,4.0) arc (180:0:0.8) -- (5.8,1);
  \draw (1.2,3) -- (2.8,3);
  \draw (4.2,1.8) -- (5.8,1.8);
  % electrodes
  \draw[fill=black!60] (1.85,-0.1) rectangle (2.15,1.6);
  \draw[fill=black!60] (4.85,-0.1) rectangle (5.15,1.6);
  % wires and cell
  \draw[thick] (2,-0.1) -- (2,-1.2) -- (3.2,-1.2);
  \draw[thick] (5,-0.1) -- (5,-1.2) -- (3.8,-1.2);
  \draw[very thick] (3.2,-0.8) -- (3.2,-1.6);
  \draw[very thick] (3.8,-1.0) -- (3.8,-1.4);
  \node at (2.9,-0.9) {$+$};
  \node at (4.1,-0.9) {$-$};
  % labels
  \node at (2,3.7) {gas X};
  \node at (5,3.0) {gas Y};
  \draw (2,1.4) -- (-1.2,1.4) node[left] {carbon electrode};
  \draw (6.5,2.0) -- (8.0,2.0) node[right] {dilute sodium chloride solution};
  \node at (3.5,-2.3) {Fig. 3.1};
\end{tikzpicture}
